BEGIN;
SET LOCAL statement_timeout='35s';
CREATE TEMP TABLE invite_qa(label text,passed boolean);
GRANT ALL ON invite_qa TO service_role;
SET LOCAL ROLE service_role;
DO $$
DECLARE w uuid;actor uuid;t uuid:=gen_random_uuid();c uuid:=gen_random_uuid();op uuid;payload jsonb;assignments jsonb;people jsonb;credentials jsonb;summary jsonb;portal jsonb;i public.case_participant_invitations;j public.case_participant_invitations;renewed uuid;blocked boolean;
BEGIN
 SELECT m.workspace_id,m.user_id INTO w,actor FROM public.workspace_members m JOIN public.workspaces ws ON ws.id=m.workspace_id WHERE m.status='active' AND m.role='owner' AND (m.access_expires_at IS NULL OR m.access_expires_at>now()) AND coalesce((ws.organization_settings#>>'{case_review,separationOfDuties}')::boolean,false)=false LIMIT 1;
 IF w IS NULL THEN RAISE EXCEPTION 'QA_NO_WORKSPACE';END IF;
 payload:=jsonb_build_object('name','QA INVITATION ROLLBACK','description','','case_type','QA','requirements_schema',jsonb_build_object('version',6,'workflowMode','simple','sections',jsonb_build_array(jsonb_build_object('id','section','title','QA','items',jsonb_build_array(jsonb_build_object('id','item','kind','requested_document','title','Acta QA','required',true,'requiresReview',true,'reviewerRole','owner','requiresSignature',false)))),'verifications','[]'::jsonb,'stages','[]'::jsonb,'reviewPolicy',jsonb_build_object('version',1,'reviewTiming','progressive','approval',jsonb_build_object('enabled',false,'role',null),'completion',jsonb_build_object('mode','manual','role','owner'))),'forms_schema','[]'::jsonb);
 PERFORM public.case_control_publish(t,actor,w,null,payload);
 assignments:=jsonb_build_object('closer',actor,'reviewers',jsonb_build_object('item',actor));
 people:=jsonb_build_array(jsonb_build_object('name','Contacto QA','email','contact@example.invalid','role','contact'));
 credentials:=jsonb_build_array(jsonb_build_object('hash',repeat('1',64),'ciphertext',repeat('x',100)),jsonb_build_object('hash',repeat('2',64),'ciphertext',repeat('y',100)));
 PERFORM public.case_launch_invited(t,actor,'QA INVITATION','Titular QA',null,assignments,c,'primary@example.invalid',people,credentials,'https://example.invalid');
 IF (SELECT count(*) FROM public.case_participant_invitations WHERE case_file_id=c)<>2 THEN RAISE EXCEPTION 'QA_QUEUE';END IF;
 INSERT INTO invite_qa VALUES('case launch atomically queues every selected participant',true);
 PERFORM public.case_launch_invited(t,actor,'QA INVITATION','Titular QA',null,assignments,c,'primary@example.invalid',people,credentials,'https://other.invalid');
 IF (SELECT count(*) FROM public.case_participant_invitations WHERE case_file_id=c)<>2 OR EXISTS(SELECT 1 FROM public.case_participant_invitations WHERE case_file_id=c AND app_origin<>'https://example.invalid') THEN RAISE EXCEPTION 'QA_DUPLICATE';END IF;
 INSERT INTO invite_qa VALUES('launch retry preserves recipients, links and original origin',true);
 op:=gen_random_uuid();blocked:=false;BEGIN PERFORM public.case_launch_invited(t,actor,'QA INCOMPLETE','Titular QA',null,assignments,op,'primary@example.invalid',people,'[]','https://example.invalid');EXCEPTION WHEN raise_exception THEN IF SQLERRM='CASE_INVITATION_INVALID' THEN blocked:=true;ELSE RAISE;END IF;END;
 IF NOT blocked OR EXISTS(SELECT 1 FROM public.case_files WHERE id=op) THEN RAISE EXCEPTION 'QA_PARTIAL_CREATION';END IF;
 INSERT INTO invite_qa VALUES('missing delivery capability rolls back the entire new case',true);
 PERFORM public.case_invitation_claim(c,actor);
 IF (SELECT count(*) FROM public.case_invitation_claim(c,actor))<>0 THEN RAISE EXCEPTION 'QA_CONCURRENT_CLAIM';END IF;
 SELECT * INTO i FROM public.case_participant_invitations WHERE case_file_id=c AND participant_role='subject';SELECT * INTO j FROM public.case_participant_invitations WHERE case_file_id=c AND participant_role='contact';
 INSERT INTO invite_qa VALUES('active delivery leases prevent concurrent sends',true);
 IF public.case_invitation_payload(i.id,i.claim_id,'first-encrypted-payload')<>public.case_invitation_payload(i.id,i.claim_id,'different-payload') THEN RAISE EXCEPTION 'QA_PAYLOAD_CHANGED';END IF;
 IF public.case_invitation_finish(i.id,gen_random_uuid(),'sent','provider-id','ACCEPTED') THEN RAISE EXCEPTION 'QA_STALE_CLAIM';END IF;
 PERFORM public.case_invitation_finish(i.id,i.claim_id,'sent','provider-id','PROVIDER_ACCEPTED');
 IF (SELECT count(*) FROM public.case_invitation_claim(c,actor))<>0 THEN RAISE EXCEPTION 'QA_SENT_RECLAIMED';END IF;
 INSERT INTO invite_qa VALUES('frozen payload, claim ownership and accepted sends survive retries',true);
 portal:=public.case_invitation_portal(i.token_hash);
 IF jsonb_array_length(portal->'requirements')<>1 OR portal ? 'email' OR portal ? 'token_ciphertext' OR portal ? 'participants' THEN RAISE EXCEPTION 'QA_PORTAL_PRIVACY';END IF;
 IF jsonb_array_length(public.case_invitation_portal(j.token_hash)->'requirements')<>0 THEN RAISE EXCEPTION 'QA_OTHER_PARTICIPANT_CONTENT';END IF;
 INSERT INTO invite_qa VALUES('portal exposes only the invited participant scope',true);
 IF EXISTS(SELECT 1 FROM public.case_file_invitations WHERE case_file_id=c) OR (SELECT status FROM public.case_files WHERE id=c)<> 'integrating' THEN RAISE EXCEPTION 'QA_VERIFICATION_CONFUSION';END IF;
 INSERT INTO invite_qa VALUES('opening an invite does not verify identity or approve/close a case',true);
 PERFORM public.case_invitation_finish(j.id,j.claim_id,'retrying',null,'TIMEOUT');
 UPDATE public.case_participant_invitations SET first_attempt_at=now()-interval '24 hours' WHERE id=j.id;
 PERFORM public.case_invitation_claim(c,actor);
 IF (SELECT delivery_status FROM public.case_participant_invitations WHERE id=j.id)<>'attention' THEN RAISE EXCEPTION 'QA_UNSAFE_OLD_RETRY';END IF;
 INSERT INTO invite_qa VALUES('ambiguous sends stop before provider deduplication expires',true);
 op:=gen_random_uuid();renewed:=public.case_invitation_manage(c,actor,i.id,'renew',op,jsonb_build_object('hash',repeat('3',64),'ciphertext',repeat('z',100)));
 IF public.case_invitation_manage(c,actor,i.id,'renew',op,jsonb_build_object('hash',repeat('4',64),'ciphertext',repeat('z',100)))<>renewed OR public.case_invitation_portal(i.token_hash) IS NOT NULL OR public.case_invitation_portal(repeat('3',64)) IS NULL THEN RAISE EXCEPTION 'QA_RENEWAL';END IF;
 INSERT INTO invite_qa VALUES('new invitation is retry-safe and immediately invalidates the previous link',true);
 PERFORM public.case_invitation_manage(c,actor,renewed,'revoke',gen_random_uuid(),'{}');
 IF public.case_invitation_portal(repeat('3',64)) IS NOT NULL THEN RAISE EXCEPTION 'QA_REVOKED_LINK';END IF;
 UPDATE public.case_participant_invitations SET expires_at=now()-interval '1 second' WHERE id=j.id;
 IF public.case_invitation_portal(j.token_hash) IS NOT NULL OR public.case_invitation_portal(repeat('f',64)) IS NOT NULL THEN RAISE EXCEPTION 'QA_EXPIRED_LINK';END IF;
 INSERT INTO invite_qa VALUES('revoked, expired and unknown links are rejected',true);
 blocked:=false;BEGIN PERFORM public.case_invitation_summary(c,gen_random_uuid());EXCEPTION WHEN insufficient_privilege THEN blocked:=true;END;
 IF NOT blocked OR has_table_privilege('authenticated','public.case_participant_invitations','SELECT') OR has_function_privilege('anon','public.case_invitation_portal(text)','EXECUTE') THEN RAISE EXCEPTION 'QA_TENANT_BOUNDARY';END IF;
 INSERT INTO invite_qa VALUES('foreign actors and public Data API access are denied',true);
 summary:=public.case_invitation_summary(c,actor);
 IF jsonb_array_length(summary)<>2 OR summary::text LIKE '%ciphertext%' OR summary::text LIKE '%token_hash%' THEN RAISE EXCEPTION 'QA_SUMMARY_LEAK';END IF;
 INSERT INTO invite_qa VALUES('sender receives current per-person delivery status without capabilities',true);
END;
$$;
RESET ROLE;
SELECT * FROM invite_qa;
ROLLBACK;
